   125	function getLatestErrorFieldForAnyField<TOnyxData extends OnyxDataWithErrorFields>(onyxData: OnyxEntry<TOnyxData>): Errors {
   126	    const errorFields = onyxData?.errorFields ?? {};
   127	
   128	    if (Object.keys(errorFields).length === 0) {
   129	        return {};
   130	    }
   131	
   132	    const fieldNames = Object.keys(errorFields);
   133	    const latestErrorFields = fieldNames.map((fieldName) => getLatestErrorField(onyxData, fieldName));
   134	    return latestErrorFields.reduce((acc, error) => Object.assign(acc, error), {});
   135	}
