    35	}: NamePageProps) {
    36	    const styles = useThemeStyles();
    37	    const {translate} = useLocalize();
    38	    const currentTaxRate = PolicyUtils.getTaxByID(policy, taxID);
    39	    const {inputCallbackRef} = useAutoFocusInput();
    40	
    41	    const [name, setName] = useState(() => Parser.htmlToMarkdown(currentTaxRate?.name ?? ''));
    42	
    43	    const goBack = useCallback(() => Navigation.goBack(ROUTES.WORKSPACE_TAX_EDIT.getRoute(policyID ?? '-1', taxID)), [policyID, taxID]);
    44	
    45	    const submit = () => {
    46	        const taxName = name.trim();
    47	        // Do not call the API if the edited tax name is the same as the current tag name
    48	        if (currentTaxRate?.name !== taxName) {
    49	            renamePolicyTax(policyID, taxID, taxName);
    50	        }
    51	        goBack();
    52	    };
    53	
    54	    const validate = useCallback(
    55	        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.WORKSPACE_TAX_NAME_FORM>) => {
    56	            if (!policy) {
    57	                return {};
    58	            }
    59	            if (values[INPUT_IDS.NAME] === currentTaxRate?.name) {
    60	                return {};
    61	            }
    62	            return validateTaxName(policy, values);
    63	        },
    64	        [currentTaxRate?.name, policy],
    65	    );
    66	
    67	    if (!currentTaxRate) {
    68	        return <NotFoundPage />;
    69	    }
    70	
    71	    return (
    72	        <AccessOrNotFoundWrapper
    73	            accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
    74	            policyID={policyID}
    75	            featureName={CONST.POLICY.MORE_FEATURES.ARE_TAXES_ENABLED}
    76	        >
    77	            <ScreenWrapper
    78	                includeSafeAreaPaddingBottom={false}
    79	                shouldEnableMaxHeight
    80	                testID={NamePage.displayName}
    81	            >
    82	                <HeaderWithBackButton
    83	                    title={translate('common.name')}
    84	                    onBackButtonPress={goBack}
    85	                />
    86	
    87	                <FormProvider
    88	                    formID={ONYXKEYS.FORMS.WORKSPACE_TAX_NAME_FORM}
    89	                    submitButtonText={translate('workspace.editor.save')}
    90	                    style={[styles.flexGrow1, styles.ph5]}
    91	                    onSubmit={submit}
    92	                    enabledWhenOffline
    93	                    validate={validate}
    94	                >
    95	                    <View style={styles.mb4}>
    96	                        <InputWrapper
    97	                            InputComponent={TextInput}
    98	                            role={CONST.ROLE.PRESENTATION}
    99	                            inputID={INPUT_IDS.NAME}
   100	                            label={translate('workspace.editor.nameInputLabel')}
   101	                            accessibilityLabel={translate('workspace.editor.nameInputLabel')}
   102	                            value={name}
   103	                            maxLength={CONST.TAX_RATES.NAME_MAX_LENGTH}
   104	                            onChangeText={setName}
   105	                            ref={inputCallbackRef}
   106	                        />
   107	                    </View>
   108	                </FormProvider>
   109	            </ScreenWrapper>
   110	        </AccessOrNotFoundWrapper>
   111	    );
   112	}
   113	
   114	NamePage.displayName = 'NamePage';
   115	
   116	export default withPolicyAndFullscreenLoading(NamePage);
